use crate::wasi::clocks::wall_clock;

struct Node;

/// Civil date (proleptic Gregorian) from days since 1970-01-01.
/// Howard Hinnant's `civil_from_days` algorithm.
fn civil_from_days(days: i64) -> (i64, u32, u32) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z - era * 146_097;
    let yoe = (doe - doe / 1_460 + doe / 36_524 - doe / 146_096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let y = if m <= 2 { y + 1 } else { y };
    (y, m as u32, d as u32)
}

impl Guest for Node {
    fn run(_tick: Tick) -> RunInfo {
        let now = wall_clock::now();
        let started: u64 = now.seconds;

        let days = (started / 86_400) as i64;
        let (y, m, d) = civil_from_days(days);

        // Clamp the year so the rendered date is always exactly YYYY-MM-DD (10 chars).
        let y = y.clamp(0, 9_999);

        RunInfo {
            date: format!("{:04}-{:02}-{:02}", y, m, d),
            started,
        }
    }
}

export!(Node);
